INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C1','kor',2,1,'u2',1,'비의 이름과 특징 — 가랑비·이슬비·단비·잠비·찬비·장대비처럼 비의 이름에 굵기·때·느낌 같은 특징이 담겨 있음을 알고, 특징이 드러나게 새 이름 붙이기',ARRAY['2국05-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C2','kor',2,1,'u2',1,'첫 글자가 같은 낱말과 글자 모으기 — 「비」로 시작하는 낱말처럼 첫 글자가 같은 낱말을 떠올리고, 주변 글자(친절+도구 → 친구)·글자 카드를 모아 낱말 만들기',ARRAY['2국05-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C3','kor',2,1,'u2',3,'다섯 글자 말놀이와 규칙 — 「내 친구 몬덕이」처럼 다섯 글자로 대화하되 말을 억지로 늘이거나 끊어 말이 안 되게 하지 않기',ARRAY['2국05-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C4','kor',2,1,'u2',3,'말놀이의 좋은 점과 주의점 — 재미있고 여러 낱말을 자연스럽게 익히며 다양한 말로 생각을 표현할 수 있음, 앞사람 말을 귀 기울여 듣고 규칙을 지키며 승부보다 협력하기',ARRAY['2국05-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C5','kor',2,1,'u2',3,'꼬리따기·주고받는·말 덧붙이기 놀이 — 「사과는 빨개」처럼 앞말의 꼬리를 물어 비슷한 것을 잇기, 「하나는 뭐니?」처럼 묻고 답하기, 앞 친구 말을 반복하고 그 장소에 있는 것을 덧붙이기',ARRAY['2국05-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C6','kor',2,1,'u2',6,'「어디까지 왔니」 노래와 노랫말 바꾸기 — 어디까지 왔는지 묻고 답하며 장소가 되풀이되는 전래 동요의 특징을 알고, 장소 자리에 다른 장소를 넣어 노랫말 바꾸기',ARRAY['2국05-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C7','kor',2,1,'u2',6,'장소마다 볼 수 있는 낱말 — 채소 가게·놀이터·학교처럼 장소를 떠올리고 그곳에서 볼 수 있는 물건의 이름을 모아 낱말 밭 만들기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C8','kor',2,1,'u2',6,'낱말로 문장 만들기와 줄줄이 이야기 — 서로 관계없어 보이는 두 낱말을 모두 넣어 문장 만들기, 앞 문장과 내용이 이어지게 한 문장씩 덧붙여 모둠이 함께 이야기 만들기',ARRAY['2국03-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C9','kor',2,1,'u2',8,'「시원한 책」과 「시원하다」의 여러 쓰임 — 그림과 글을 함께 살피며 읽고, 서늘할 때·뜨겁고 얼큰한 음식이 속을 후련하게 할 때·말끔해져 기분 좋을 때·막힘없을 때(시원시원하다)처럼 같은 말이 상황마다 되풀이되는 재미 느끼기',ARRAY['2국02-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C10','kor',2,1,'u2',8,'재미있는 문장·장면 찾아 생각이나 느낌 나누기 — 글에서 재미있는 문장이나 장면과 그 까닭을 말하고, 친구와 같으면 공감하고 다르면 생각이 서로 다름을 존중하며, 시원했던 경험을 생각그물로 넓히기',ARRAY['2국02-05']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C11','kor',2,1,'u2',10,'좋아하는 문장 찾아 책갈피로 소개하기 — 도서관에서 여러 책을 살펴 읽고 싶은 책을 고르고, 재미있거나 감동을 주는 문장을 찾아 한쪽엔 문장·한쪽엔 책 제목을 쓴 책갈피를 만들어 고른 까닭과 함께 소개하기',ARRAY['2국02-05']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C12','kor',2,1,'u2',12,'낱말을 활용한 재미있는 이름 짓기와 말놀이 잔치 — 「콩콩콩 콩떡」처럼 소리·재료·맛·모양을 살려 식당과 음식 이름을 짓고, 규칙을 지켜 말놀이 잔치·시장 낱말 말하기 놀이를 협동하며 하기',ARRAY['2국03-02']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C13','kor',2,1,'u2',12,'첫소리·낱말 뜻을 살린 말놀이 — 「ㅍㄷ」·「ㅅㅅㅎ」처럼 같은 첫소리로 시작하는 낱말 떠올리기, 싱숭해·시시해 같은 낱말의 뜻을 살려 문장 만들기, 화살표를 따라 문장 완성하기(국어활동·기초 다지기)',ARRAY['2국05-01']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X01','kor',2,'u2',ARRAY['K2-1-u2-C1']::text[],'비의 이름은 비의 특징과 관계없이 그냥 붙은 것이라 여긴다','이름 속 낱말(이슬·장대·잠)을 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X02','kor',2,'u2',ARRAY['K2-1-u2-C2','K2-1-u2-C13']::text[],'첫 글자(첫소리)가 같은 낱말을 고를 때 끝이나 가운데 글자가 같은 낱말을 고른다','맨 앞 글자를 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X03','kor',2,'u2',ARRAY['K2-1-u2-C3']::text[],'다섯 글자 말놀이에서 글자 수만 맞추려고 말을 억지로 늘이거나 끊는다','뜻이 통하는 다섯 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X04','kor',2,'u2',ARRAY['K2-1-u2-C4','K2-1-u2-C12']::text[],'말놀이는 친구를 이기는 승부가 목적이라 여겨 틀린 친구를 탓하거나 놀린다','함께 길게 이어 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X05','kor',2,'u2',ARRAY['K2-1-u2-C5']::text[],'꼬리따기에서 앞말의 꼬리와 관계없는 말을 잇는다','앞말 끝을 물고 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X06','kor',2,'u2',ARRAY['K2-1-u2-C5','K2-1-u2-C12']::text[],'말 덧붙이기에서 앞 친구 말을 반복하지 않거나 그 장소와 관계없는 것을 덧붙인다','앞말 반복 + 그곳에 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X07','kor',2,'u2',ARRAY['K2-1-u2-C5']::text[],'주고받는 말놀이에서 물음과 맞지 않는 답을 한다','물음을 다시 듣고 수·모양 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X08','kor',2,'u2',ARRAY['K2-1-u2-C6']::text[],'노랫말을 바꿀 때 묻고 답하는 틀과 장소 자리를 지키지 않는다','장소 자리만 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X09','kor',2,'u2',ARRAY['K2-1-u2-C7','K2-1-u2-C12']::text[],'장소와 관계없는 물건을 그 장소에서 볼 수 있는 낱말로 고른다','「그곳에 가면 보일까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X10','kor',2,'u2',ARRAY['K2-1-u2-C8']::text[],'두 낱말로 문장을 만들 때 한 낱말을 빠뜨린다','두 낱말 모두 들어갔나 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X11','kor',2,'u2',ARRAY['K2-1-u2-C8']::text[],'줄줄이 이야기에서 앞 문장과 이어지지 않는 문장을 붙인다','앞 문장 다시 읽고 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X12','kor',2,'u2',ARRAY['K2-1-u2-C9']::text[],'「시원하다」는 차갑다는 뜻으로만 쓴다고 여긴다','「어떤 장면의 시원함일까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X13','kor',2,'u2',ARRAY['K2-1-u2-C10','K2-1-u2-C11']::text[],'재미있는 부분이나 좋아하는 문장은 정답이 하나라서 친구와 다르면 틀렸다고 여긴다','느낌은 사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X14','kor',2,'u2',ARRAY['K2-1-u2-C10','K2-1-u2-C11']::text[],'문장이나 장면을 소개할 때 고른 까닭이나 책 제목을 빠뜨린다','문장 + 책 제목 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X15','kor',2,'u2',ARRAY['K2-1-u2-C12','K2-1-u2-C13']::text[],'낱말의 소리나 뜻을 살피지 않고 이름을 짓거나 문장에 넣는다','소리·뜻이 살아 있나 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
