INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#7','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C4',3,'mc','auto','책으로 성 쌓기 놀이를 할 때 알맞은 모습은?',ARRAY['K2-1-u2-X04']::text[],false,'{"seq":7,"concept":"K2-1-u2-C4","difficulty":3,"kind":"mc","stem":"책으로 성 쌓기 놀이를 할 때 알맞은 모습은?","options":[{"t":"친구들과 힘을 모아 책을 차례로 쌓아요","correct":true},{"t":"혼자 다 쌓겠다고 책을 빼앗아요","mis":"K2-1-u2-X04"},{"t":"먼저 쌓는 사람이 이겼다고 놀려요","mis":"K2-1-u2-X04"}],"explanation":["협력해요.","지도서 95쪽이에요.","함께 놀아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#8','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'sa','auto','가랑비보다 더 가늘게 내려서 풀잎에 이슬이 겨우 맺힐 만큼 내리는 비의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u2-C1","difficulty":4,"kind":"sa","stem":"가랑비보다 더 가늘게 내려서 풀잎에 이슬이 겨우 맺힐 만큼 내리는 비의 이름을 쓰세요.","answer":["이슬비"],"explanation":["이슬비예요.","44쪽이에요.","가장 가는 비예요."],"asset":{"type":"passage","lines":["가늘게 내리는 비는 가랑비 — 국숫발처럼 가늘어서 붙은 이름이에요.","가랑비보다 더 가는 비는 이슬비 — 풀잎에 이슬이 겨우 맺힐 만큼 내려요."],"title":"『국어』 44쪽 「가랑비와 이슬비」(박남일) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#9','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'essay','teacher','45쪽 3번 — 비가 내리는 모습을 떠올려 특징이 드러나게 새 이름을 붙이고, 그렇게 붙인 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C1","difficulty":4,"kind":"essay","stem":"45쪽 3번 — 비가 내리는 모습을 떠올려 특징이 드러나게 새 이름을 붙이고, 그렇게 붙인 까닭을 쓰세요.","answer_guide":{"answer":"예: 「톡톡비」 — 창문에 톡톡 부딪치며 떨어지는 소리가 나서","scoring_points":["새 이름을 지었어요","비의 특징이 드러난 까닭을 썼어요"]},"explanation":["이름과 까닭이에요.","45쪽 3번이에요.","지도서 95쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#10','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',4,'essay','teacher','「비」 말고 다른 글자 하나를 골라, 그 글자로 시작하는 낱말을 세 개 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C2","difficulty":4,"kind":"essay","stem":"「비」 말고 다른 글자 하나를 골라, 그 글자로 시작하는 낱말을 세 개 쓰세요.","answer_guide":{"answer":"예: 「고」 — 고구마, 고래, 고양이","scoring_points":["고른 글자를 썼어요","그 글자로 시작하는 낱말을 세 개 썼어요"]},"explanation":["첫 글자 놀이예요.","45쪽 4번이에요.","지도서 95쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
