INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#8','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',4,'sa','auto','「사과는 빨개」처럼 앞말의 꼬리를 물어 비슷한 것을 떠올려 이어 가는 말놀이를 네 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u2-C5","difficulty":4,"kind":"sa","stem":"「사과는 빨개」처럼 앞말의 꼬리를 물어 비슷한 것을 떠올려 이어 가는 말놀이를 네 글자로 쓰세요.","answer":["꼬리따기"],"explanation":["꼬리따기예요.","48쪽이에요.","꼬리를 물어요."],"asset":{"type":"passage","lines":["사과는 빨개 / 빨가면 딸기","딸기는 작아 / 작으면 아기","아기는 귀여워 / 귀여우면 곰 인형","곰 인형은 포근해 / 포근하면 봄"],"title":"『국어』 48쪽 전래 동요 「사과는 빨개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#9','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',4,'essay','teacher','49쪽 (2) — 주고받는 말놀이를 이어 쓰세요. 「넷은 뭐니?」, 「다섯은 뭐니?」에 알맞은 답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C5","difficulty":4,"kind":"essay","stem":"49쪽 (2) — 주고받는 말놀이를 이어 쓰세요. 「넷은 뭐니?」, 「다섯은 뭐니?」에 알맞은 답을 쓰세요.","answer_guide":{"answer":"예: 넷은 뭐니? 소의 다리 넷 / 다섯은 뭐니? 발가락 다섯","scoring_points":["넷에 맞는 답을 썼어요","다섯에 맞는 답을 썼어요"]},"explanation":["묻고 답해요.","49쪽이에요.","수를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
