INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#6','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'mc','auto','「빵집」에서 볼 수 있는 것만 모은 것은?',ARRAY['K2-1-u2-X09']::text[],false,'{"seq":6,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"「빵집」에서 볼 수 있는 것만 모은 것은?","options":[{"t":"식빵 · 케이크 · 쟁반","correct":true},{"t":"식빵 · 철봉 · 그네","mis":"K2-1-u2-X09"},{"t":"케이크 · 칠판 · 실내화","mis":"K2-1-u2-X09"}],"explanation":["빵집의 낱말이에요.","지도서 103쪽이에요.","장소를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#7','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',3,'mc','auto','노랫말 「어디까지 왔니 / 동네 앞에 왔다」를 「동물원」을 넣어 바꾼 것은?',ARRAY['K2-1-u2-X08']::text[],false,'{"seq":7,"concept":"K2-1-u2-C6","difficulty":3,"kind":"mc","stem":"노랫말 「어디까지 왔니 / 동네 앞에 왔다」를 「동물원」을 넣어 바꾼 것은?","options":[{"t":"「어디까지 왔니 / 동물원에 왔다」","correct":true},{"t":"「어디까지 왔니 / 사자를 보았다」","mis":"K2-1-u2-X08"},{"t":"「동물원은 어디니 / 동네 앞에 왔다」","mis":"K2-1-u2-X08"}],"explanation":["장소 자리예요.","지도서 102쪽이에요.","틀을 지켜요."],"asset":{"type":"passage","lines":["어디까지 왔니 / 아직 아직 멀었다","어디까지 왔니 / 동네 앞에 왔다","어디까지 왔니 / 개울가에 왔다","어디까지 왔니 / 대문 앞에 다 왔다"],"title":"『국어』 52쪽 전래 동요 「어디까지 왔니」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#8','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C8',4,'sa','auto','한 문장씩 앞 문장과 이어지게 덧붙이며 모둠이 함께 이야기를 만드는 놀이를 「(    ) 이야기 만들기」라고 해요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u2-C8","difficulty":4,"kind":"sa","stem":"한 문장씩 앞 문장과 이어지게 덧붙이며 모둠이 함께 이야기를 만드는 놀이를 「(    ) 이야기 만들기」라고 해요. 빈칸 세 글자를 쓰세요.","answer":["줄줄이"],"explanation":["줄줄이예요.","55쪽이에요.","이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#9','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C8',4,'essay','teacher','53쪽 낱말 가운데 서로 관계없어 보이는 두 낱말(예: 시소, 배추)을 골라 두 낱말이 모두 들어간 문장을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C8","difficulty":4,"kind":"essay","stem":"53쪽 낱말 가운데 서로 관계없어 보이는 두 낱말(예: 시소, 배추)을 골라 두 낱말이 모두 들어간 문장을 쓰세요.","answer_guide":{"answer":"예: 시소, 배추 — 커다란 배추가 시소 한쪽에 앉아 있어서 시소가 쿵 내려갔다.","scoring_points":["고른 두 낱말을 썼어요","두 낱말이 모두 들어간 문장을 썼어요"]},"explanation":["두 낱말 문장이에요.","54쪽이에요.","상상을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#10','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C8',4,'essay','teacher','55쪽 예시 이야기 세 문장 다음에 이어질 문장을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C8","difficulty":4,"kind":"essay","stem":"55쪽 예시 이야기 세 문장 다음에 이어질 문장을 하나 쓰세요.","answer_guide":{"answer":"예: 다행히 짝이 준비물을 빌려주어서 마음이 놓였다.","scoring_points":["앞 문장과 이어지는 문장을 썼어요","준비물 이야기를 이어 갔어요"]},"explanation":["이어 써요.","55쪽이에요.","앞 문장과 이어요."],"asset":{"type":"passage","lines":["아침에 오이가 들어간 김밥을 먹었다.","김밥을 다 먹고 준비물을 빨리 챙겼다.","학교에 와 보니 준비물을 잘못 가져와서 가슴이 콩닥콩닥 뛰었다."],"title":"『국어』 55쪽 줄줄이 이야기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#1','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',1,'mc','auto','「시원한 책」에서 장면마다 되풀이되는 말은?',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":1,"concept":"K2-1-u2-C9","difficulty":1,"kind":"mc","stem":"「시원한 책」에서 장면마다 되풀이되는 말은?","options":[{"t":"시원하다","correct":true},{"t":"뜨겁다","mis":"K2-1-u2-X12"},{"t":"슬프다","mis":"K2-1-u2-X12"}],"explanation":["시원하다예요.","56~61쪽이에요.","같은 말이 되풀이돼요."],"asset":{"type":"passage","lines":["그림책 속에서 「시원하다」는 말이 장면마다 되풀이돼요.","더운 날 차가운 물을 마시고 「캬하, 시원하다!」","뜨겁고 얼큰한 국물을 먹을 때도 시원해요.","깨끗하게 씻어 말끔해졌을 때도 시원해요.","막힘없는 큰 목소리에는 「시원시원하네!」"],"title":"『국어』 56~61쪽 「시원한 책」(이수연) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#2','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',1,'mc','auto','더운 날 차가운 물을 마신 뒤 할 만한 말은?',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":2,"concept":"K2-1-u2-C9","difficulty":1,"kind":"mc","stem":"더운 날 차가운 물을 마신 뒤 할 만한 말은?","options":[{"t":"「캬하, 시원하다!」","correct":true},{"t":"「아이, 추워!」","mis":"K2-1-u2-X12"},{"t":"「앗, 뜨거워!」","mis":"K2-1-u2-X12"}],"explanation":["시원해요.","56쪽이에요.","책 속 말이에요."],"asset":{"type":"passage","lines":["그림책 속에서 「시원하다」는 말이 장면마다 되풀이돼요.","더운 날 차가운 물을 마시고 「캬하, 시원하다!」","뜨겁고 얼큰한 국물을 먹을 때도 시원해요.","깨끗하게 씻어 말끔해졌을 때도 시원해요.","막힘없는 큰 목소리에는 「시원시원하네!」"],"title":"『국어』 56~61쪽 「시원한 책」(이수연) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
