INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#5','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',2,'match','auto','「시원하다」의 쓰임과 어울리는 장면을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K2-1-u2-C9","difficulty":2,"kind":"match","stem":"「시원하다」의 쓰임과 어울리는 장면을 이어 보세요.","pairs":[{"l":"더위를 식힐 만큼 서늘할 때","r":"선풍기 바람을 쐬어요"},{"l":"음식이 뜨겁고 얼큰해 속이 후련할 때","r":"뜨끈한 국물을 마셔요"},{"l":"지저분하던 것이 말끔해져 기분 좋을 때","r":"방을 깨끗이 청소해요"}],"mis":"K2-1-u2-X12","explanation":["여러 쓰임이에요.","62쪽이에요.","지도서 105쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
