INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#7','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','읽기 전에 떠올린 시원한 경험과 읽은 뒤 생각그물을 견주면 알 수 있는 것은?',ARRAY['K2-1-u2-X13']::text[],false,'{"seq":7,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"읽기 전에 떠올린 시원한 경험과 읽은 뒤 생각그물을 견주면 알 수 있는 것은?","options":[{"t":"친구들과 함께 하니 생각이 더 넓어졌어요","correct":true},{"t":"생각은 처음과 꼭 같아야 해요","mis":"K2-1-u2-X13"},{"t":"생각그물은 혼자 만들어야 해요","mis":"K2-1-u2-X13"}],"explanation":["넓어졌어요.","지도서 107쪽이에요.","협력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#8','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'sa','auto','「시원한 책」에서 장면마다 되풀이되는 낱말을 「○○하다」 꼴로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u2-C9","difficulty":4,"kind":"sa","stem":"「시원한 책」에서 장면마다 되풀이되는 낱말을 「○○하다」 꼴로 쓰세요.","answer":["시원하다"],"explanation":["시원하다예요.","56~61쪽이에요.","되풀이돼요."],"asset":{"type":"passage","lines":["그림책 속에서 「시원하다」는 말이 장면마다 되풀이돼요.","더운 날 차가운 물을 마시고 「캬하, 시원하다!」","뜨겁고 얼큰한 국물을 먹을 때도 시원해요.","깨끗하게 씻어 말끔해졌을 때도 시원해요.","막힘없는 큰 목소리에는 「시원시원하네!」"],"title":"『국어』 56~61쪽 「시원한 책」(이수연) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#9','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C10',4,'essay','teacher','63쪽 — 「시원한 책」에서 재미있었던 문장이나 장면을 하나 쓰고, 재미있었던 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"63쪽 — 「시원한 책」에서 재미있었던 문장이나 장면을 하나 쓰고, 재미있었던 까닭을 쓰세요.","answer_guide":{"answer":"예: 이를 닦는 장면 — 지저분하던 교실을 친구들과 깨끗하게 청소했던 때가 생각났기 때문이다.","scoring_points":["문장이나 장면을 썼어요","재미있었던 까닭을 썼어요"]},"explanation":["장면과 까닭이에요.","63쪽이에요.","지도서 105쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#10','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'essay','teacher','63쪽 — 내가 시원하다고 느꼈던 상황을 하나 쓰고, 어떤 시원함이었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"63쪽 — 내가 시원하다고 느꼈던 상황을 하나 쓰고, 어떤 시원함이었는지 쓰세요.","answer_guide":{"answer":"예: 숙제를 다 끝냈을 때 — 마음이 탁 트이고 후련해서 시원했다.","scoring_points":["시원했던 상황을 썼어요","어떤 시원함인지 썼어요"]},"explanation":["내 경험이에요.","63쪽이에요.","생각그물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
