INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#7','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','「제목 알아맞히기 놀이」에서 친구가 「팥죽을 노리는 호랑이를 알밤·자라·절구통이 힘을 모아 혼내 줘.」라고 했어요. 제목은?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":7,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"「제목 알아맞히기 놀이」에서 친구가 「팥죽을 노리는 호랑이를 알밤·자라·절구통이 힘을 모아 혼내 줘.」라고 했어요. 제목은?","options":[{"t":"팥죽 할멈과 호랑이","correct":true},{"t":"토끼와 거북","mis":"K2-1-u2-X14"},{"t":"해님 달님","mis":"K2-1-u2-X14"}],"explanation":["팥죽 할멈과 호랑이예요.","지도서 108쪽이에요.","인물로 맞혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
