INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#19','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C2',3,'ox','auto','「나비」는 「비」로 시작하는 낱말이다.',ARRAY['K2-1-u2-X02']::text[],false,'{"seq":19,"concept":"K2-1-u2-C2","difficulty":3,"kind":"ox","stem":"「나비」는 「비」로 시작하는 낱말이다.","answer":"X","reason_options":[{"t":"「나비」는 「나」로 시작하고 「비」로 끝나서","correct":true},{"t":"「비」가 들어 있으면 모두 「비」로 시작해서","mis":"K2-1-u2-X02"}],"mis":"K2-1-u2-X02","explanation":["끝 글자예요.","45쪽이에요.","맨 앞을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#20','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C6',3,'mc','auto','「어디까지 왔니」 노랫말을 「동물원」을 넣어 바꾼 것은?',ARRAY['K2-1-u2-X08']::text[],false,'{"seq":20,"concept":"K2-1-u2-C6","difficulty":3,"kind":"mc","stem":"「어디까지 왔니」 노랫말을 「동물원」을 넣어 바꾼 것은?","options":[{"t":"「어디까지 왔니 / 동물원에 왔다」","correct":true},{"t":"「어디까지 왔니 / 사자를 보았다」","mis":"K2-1-u2-X08"},{"t":"「동물원은 어디니 / 동네 앞에 왔다」","mis":"K2-1-u2-X08"}],"explanation":["장소 자리예요.","지도서 102쪽이에요.","틀을 지켜요."],"asset":{"type":"passage","lines":["어디까지 왔니 / 아직 아직 멀었다","어디까지 왔니 / 동네 앞에 왔다","어디까지 왔니 / 개울가에 왔다","어디까지 왔니 / 대문 앞에 다 왔다"],"title":"『국어』 52쪽 전래 동요 「어디까지 왔니」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#21','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',3,'mc','auto','「시원한 책」이 재미있는 까닭으로 가장 알맞은 것은?',ARRAY['K2-1-u2-X12','K2-1-u2-X14']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"「시원한 책」이 재미있는 까닭으로 가장 알맞은 것은?","options":[{"t":"같은 말 「시원하다」가 여러 상황에서 되풀이되어서","correct":true},{"t":"어려운 낱말이 많아서","mis":"K2-1-u2-X12"},{"t":"글자가 아주 많아서","mis":"K2-1-u2-X14"}],"explanation":["되풀이의 재미예요.","지도서 104쪽이에요.","말의 재미예요."],"asset":{"type":"passage","lines":["그림책 속에서 「시원하다」는 말이 장면마다 되풀이돼요.","더운 날 차가운 물을 마시고 「캬하, 시원하다!」","뜨겁고 얼큰한 국물을 먹을 때도 시원해요.","깨끗하게 씻어 말끔해졌을 때도 시원해요.","막힘없는 큰 목소리에는 「시원시원하네!」"],"title":"『국어』 56~61쪽 「시원한 책」(이수연) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#22','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C13',3,'mc','auto','『국어』 70쪽 화살표를 따라 완성되는 문장은?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":22,"concept":"K2-1-u2-C13","difficulty":3,"kind":"mc","stem":"『국어』 70쪽 화살표를 따라 완성되는 문장은?","options":[{"t":"아름다운 한글을 아끼고 바르게 사용하는 마음을 지녀요.","correct":true},{"t":"아름다운 우리말을 빠르게 읽는 마음을 지녀요.","mis":"K2-1-u2-X15"},{"t":"한글을 사용하지 않는 마음을 지녀요.","mis":"K2-1-u2-X15"}],"explanation":["한글을 아껴요.","70쪽이에요.","기초 다지기예요."],"asset":{"type":"scene","icon":"🧭","text":"『국어』 70쪽 글자판 — 「출발」에서 화살표를 따라 글자를 읽으면 문장이 완성돼요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#23','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C1',4,'sa','auto','가랑비보다 더 가늘어 풀잎에 이슬이 겨우 맺힐 만큼 내리는 비의 이름을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u2-C1","difficulty":4,"kind":"sa","stem":"가랑비보다 더 가늘어 풀잎에 이슬이 겨우 맺힐 만큼 내리는 비의 이름을 쓰세요.","answer":["이슬비"],"explanation":["이슬비예요.","44쪽이에요.","가장 가는 비예요."],"asset":{"type":"passage","lines":["가늘게 내리는 비는 가랑비 — 국숫발처럼 가늘어서 붙은 이름이에요.","가랑비보다 더 가는 비는 이슬비 — 풀잎에 이슬이 겨우 맺힐 만큼 내려요."],"title":"『국어』 44쪽 「가랑비와 이슬비」(박남일) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#24','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C4',4,'essay','teacher','지도서 116~117쪽 평가 — 하고 싶은 말놀이를 하나 쓰고, 그 말놀이를 할 때 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C4","difficulty":4,"kind":"essay","stem":"지도서 116~117쪽 평가 — 하고 싶은 말놀이를 하나 쓰고, 그 말놀이를 할 때 주의할 점을 쓰세요.","answer_guide":{"answer":"예: 말 덧붙이기 놀이 — 앞 친구가 한 말을 잘 기억해 그대로 반복하고, 그 장소에 있는 것을 덧붙인다.","scoring_points":["하고 싶은 말놀이를 썼어요","주의할 점을 썼어요"]},"explanation":["말놀이 계획이에요.","지도서 117쪽이에요.","규칙을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#25','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',4,'essay','teacher','지도서 118~119쪽 평가 — 자신이 읽은 책의 제목을 쓰고, 그 책에서 재미있는 문장이나 장면과 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"지도서 118~119쪽 평가 — 자신이 읽은 책의 제목을 쓰고, 그 책에서 재미있는 문장이나 장면과 까닭을 쓰세요.","answer_guide":{"answer":"예: 「시원한 책」 — 물을 마신 뒤 「캬하, 시원하다!」 하는 장면이 재미있었다. 여름에 시원한 물을 마셨던 때가 떠올랐기 때문이다.","scoring_points":["책 제목을 썼어요","재미있는 문장이나 장면을 썼어요","까닭을 썼어요"]},"explanation":["책에서 재미 찾기예요.","지도서 119쪽이에요.","정답은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#1','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C1',1,'mc','auto','가랑비보다 더 가는 비는?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"가랑비보다 더 가는 비는?","options":[{"t":"이슬비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"소나기","mis":"K2-1-u2-X01"}],"explanation":["이슬비예요.","44쪽이에요.","이슬이 맺힐 만큼이에요."],"asset":{"type":"passage","lines":["가늘게 내리는 비는 가랑비 — 국숫발처럼 가늘어서 붙은 이름이에요.","가랑비보다 더 가는 비는 이슬비 — 풀잎에 이슬이 겨우 맺힐 만큼 내려요."],"title":"『국어』 44쪽 「가랑비와 이슬비」(박남일) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
