INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#4','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',1,'mc','auto','「아기는 귀여워」 다음에 오는 말은?',ARRAY['K2-1-u2-X05']::text[],false,'{"seq":4,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"「아기는 귀여워」 다음에 오는 말은?","options":[{"t":"귀여우면 곰 인형","correct":true},{"t":"작으면 아기","mis":"K2-1-u2-X05"},{"t":"빨가면 딸기","mis":"K2-1-u2-X05"}],"explanation":["귀여우면 곰 인형이에요.","48쪽이에요.","꼬리를 물어요."],"asset":{"type":"passage","lines":["사과는 빨개 / 빨가면 딸기","딸기는 작아 / 작으면 아기","아기는 귀여워 / 귀여우면 곰 인형","곰 인형은 포근해 / 포근하면 봄"],"title":"『국어』 48쪽 전래 동요 「사과는 빨개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
