INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#19','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',3,'ox','auto','「뜨끈한 국을 먹으니 속이 시원하다.」는 바르게 쓴 문장이다.',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":19,"concept":"K2-1-u2-C9","difficulty":3,"kind":"ox","stem":"「뜨끈한 국을 먹으니 속이 시원하다.」는 바르게 쓴 문장이다.","answer":"O","reason_options":[{"t":"뜨겁고 얼큰한 음식이 속을 후련하게 할 때도 「시원하다」를 써서","correct":true},{"t":"「시원하다」는 차가울 때만 써서","mis":"K2-1-u2-X12"}],"mis":"K2-1-u2-X12","explanation":["바른 문장이에요.","62쪽이에요.","지도서 105쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#20','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',3,'mc','auto','「김밥을 다 먹고 준비물을 빨리 챙겼다.」 다음에 가장 알맞은 문장은?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":20,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"「김밥을 다 먹고 준비물을 빨리 챙겼다.」 다음에 가장 알맞은 문장은?","options":[{"t":"학교에 와 보니 준비물을 잘못 가져와서 가슴이 콩닥콩닥 뛰었다.","correct":true},{"t":"오이는 초록색 채소이다.","mis":"K2-1-u2-X11"},{"t":"우리 반 반장은 지호이다.","mis":"K2-1-u2-X11"}],"explanation":["준비물이 이어져요.","55쪽이에요.","앞 문장과 이어요."],"asset":{"type":"passage","lines":["아침에 오이가 들어간 김밥을 먹었다.","김밥을 다 먹고 준비물을 빨리 챙겼다.","학교에 와 보니 준비물을 잘못 가져와서 가슴이 콩닥콩닥 뛰었다."],"title":"『국어』 55쪽 줄줄이 이야기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#21','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',3,'mc','auto','짝과 같은 장면을 재미있다고 골랐을 때 알맞은 말은?',ARRAY['K2-1-u2-X13']::text[],false,'{"seq":21,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"짝과 같은 장면을 재미있다고 골랐을 때 알맞은 말은?","options":[{"t":"「나도 그 장면이 좋았어!」 하고 공감해요","correct":true},{"t":"「따라 하지 마.」","mis":"K2-1-u2-X13"},{"t":"「그 장면은 재미없어.」","mis":"K2-1-u2-X13"}],"explanation":["공감해요.","63쪽이에요.","지도서 105쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#22','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C13',3,'mc','auto','첫소리 「ㅅㅅㅎ」의 「ㅅㅅ」 방향을 돌려 「ㄱㄱㅎ」을 만들면 나올 수 있는 낱말은?',ARRAY['K2-1-u2-X02']::text[],false,'{"seq":22,"concept":"K2-1-u2-C13","difficulty":3,"kind":"mc","stem":"첫소리 「ㅅㅅㅎ」의 「ㅅㅅ」 방향을 돌려 「ㄱㄱㅎ」을 만들면 나올 수 있는 낱말은?","options":[{"t":"궁금해","correct":true},{"t":"섭섭해","mis":"K2-1-u2-X02"},{"t":"신선해","mis":"K2-1-u2-X02"}],"explanation":["궁금해예요.","지도서 109쪽이에요.","첫소리가 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#23','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',4,'sa','auto','「사과는 빨개」처럼 앞말의 꼬리를 물어 비슷한 것을 떠올려 이어 가는 말놀이를 네 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u2-C5","difficulty":4,"kind":"sa","stem":"「사과는 빨개」처럼 앞말의 꼬리를 물어 비슷한 것을 떠올려 이어 가는 말놀이를 네 글자로 쓰세요.","answer":["꼬리따기"],"explanation":["꼬리따기예요.","48쪽이에요.","꼬리를 물어요."],"asset":{"type":"passage","lines":["사과는 빨개 / 빨가면 딸기","딸기는 작아 / 작으면 아기","아기는 귀여워 / 귀여우면 곰 인형","곰 인형은 포근해 / 포근하면 봄"],"title":"『국어』 48쪽 전래 동요 「사과는 빨개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#24','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',4,'essay','teacher','「사과는 빨개」를 바꾸어 「바다는 파래」로 시작하는 꼬리따기 말을 두 줄 넘게 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C5","difficulty":4,"kind":"essay","stem":"「사과는 빨개」를 바꾸어 「바다는 파래」로 시작하는 꼬리따기 말을 두 줄 넘게 이어 쓰세요.","answer_guide":{"answer":"예: 바다는 파래 / 파라면 하늘 / 하늘은 높아 / 높으면 산","scoring_points":["꼬리를 물어 이었어요","두 줄 넘게 썼어요"]},"explanation":["꼬리따기예요.","48쪽이에요.","앞말 끝을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#25','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C11',4,'essay','teacher','내가 고른 좋아하는 문장을 친구에게 소개하는 말을 고른 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C11","difficulty":4,"kind":"essay","stem":"내가 고른 좋아하는 문장을 친구에게 소개하는 말을 고른 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 제가 좋아하는 문장은 「괜찮아, 다시 하면 돼.」입니다. 실수했을 때 힘이 나는 말이라서 골랐습니다.","scoring_points":["좋아하는 문장을 썼어요","고른 까닭을 썼어요"]},"explanation":["소개하는 말이에요.","65쪽이에요.","까닭이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
