INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#21','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',3,'mc','auto','「아, 시원해!」 하고 말할 만한 때는?',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"「아, 시원해!」 하고 말할 만한 때는?","options":[{"t":"가려운 등을 긁었을 때","correct":true},{"t":"손을 데었을 때","mis":"K2-1-u2-X12"},{"t":"넘어져 다쳤을 때","mis":"K2-1-u2-X12"}],"explanation":["후련해요.","60쪽이에요.","기분 좋은 시원함이에요."],"asset":{"type":"passage","lines":["그림책 속에서 「시원하다」는 말이 장면마다 되풀이돼요.","더운 날 차가운 물을 마시고 「캬하, 시원하다!」","뜨겁고 얼큰한 국물을 먹을 때도 시원해요.","깨끗하게 씻어 말끔해졌을 때도 시원해요.","막힘없는 큰 목소리에는 「시원시원하네!」"],"title":"『국어』 56~61쪽 「시원한 책」(이수연) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
