INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#24','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',4,'essay','teacher','53쪽 낱말 가운데 서로 관계없어 보이는 두 낱말을 골라 두 낱말이 모두 들어간 문장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C8","difficulty":4,"kind":"essay","stem":"53쪽 낱말 가운데 서로 관계없어 보이는 두 낱말을 골라 두 낱말이 모두 들어간 문장을 쓰세요.","answer_guide":{"answer":"예: 철봉, 오이 — 철봉에 오이가 매달려서 대롱대롱 흔들렸다.","scoring_points":["두 낱말을 골랐어요","두 낱말이 모두 들어간 문장을 썼어요"]},"explanation":["두 낱말 문장이에요.","54쪽이에요.","상상을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
