INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#24','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C1',4,'essay','teacher','비가 내리는 모습을 떠올려 특징이 드러나게 새 이름을 붙이고 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C1","difficulty":4,"kind":"essay","stem":"비가 내리는 모습을 떠올려 특징이 드러나게 새 이름을 붙이고 까닭을 쓰세요.","answer_guide":{"answer":"예: 「주룩비」 — 처마에서 주룩주룩 소리를 내며 떨어져서","scoring_points":["새 이름을 지었어요","비의 특징이 드러난 까닭을 썼어요"]},"explanation":["이름과 까닭이에요.","45쪽 3번이에요.","지도서 95쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#25','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C12',4,'essay','teacher','팔고 싶은 음식 하나를 정해 재료·맛·모양을 살린 재미있는 이름을 짓고 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C12","difficulty":4,"kind":"essay","stem":"팔고 싶은 음식 하나를 정해 재료·맛·모양을 살린 재미있는 이름을 짓고 까닭을 쓰세요.","answer_guide":{"answer":"예: 「새콤달콤 무지개 과일 꼬치」 — 여러 색 과일을 꽂아 무지개처럼 보이고 새콤달콤해서","scoring_points":["음식 이름을 지었어요","재료·맛·모양을 살린 까닭을 썼어요"]},"explanation":["음식 이름이에요.","66쪽이에요.","지도서 111쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
